 const fields=[['p','MPa'],['T','K'],['h','kJ/kg'],['s','kJ/(kg K)'],['rho','kg/m3'],['v','m3/kg'],['cp','kJ/(kg K)'],['cv','kJ/(kg K)'],['w','m/s'],['x','-']];
