function g0p(pi){let s=0;for(let k=1;k<5;k++)s+=k*G0K[k]*(pi-PI0_ICE)**(k-1);return s/PT_ICE;}
function g0pp(pi){let s=0;for(let k=2;k<5;k++)s+=k*(k-1)*G0K[k]*(pi-PI0_ICE)**(k-2);return s/(PT_ICE*PT_ICE);}
