function r2p(pi){let re_=0,im=0;for(let k=1;k<3;k++){const w=k*(pi-PI0_ICE)**(k-1);re_+=R2K[k][0]*w;im+=R2K[k][1]*w;}return [re_/PT_ICE,im/PT_ICE];}
