 if(!Number.isFinite(T)||!Number.isFinite(p)||T<=0||T>TT_ICE||p<0||p>210e6)throw Error('Лід Ih (IAPWS R10-06): потрібно 0 < T ≤ 273,16 K і 0 ≤ p ≤ 210 МПа.');
